@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root {
--bg:#0b0b13;--panel:#11111c;--line:#242432;--muted:#77778e;--text:#f4f3fa;--pink:#ff4db8;--cyan:#54e8ef;--lime:#c8f36a;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}
* {
box-sizing:border-box}
body {
margin:0;background:radial-gradient(ellipse at 50% -18%,#282044 0,transparent 55%),var(--bg);color:var(--text);font-family:var(--sans);min-height:100vh}
button {
font:inherit;color:inherit;cursor:pointer}
button:focus-visible,input:focus-visible {
outline:2px solid var(--cyan);outline-offset:3px}
.app {
max-width:1440px;margin:auto;padding:0 40px 32px}
.topbar {
height:78px;border-bottom:1px solid #ffffff12;display:flex;align-items:center;justify-content:space-between}
.brand {
display:flex;align-items:center;gap:12px;font-size:17px;font-weight:700;letter-spacing:.13em}
.brand-icon {
width:32px;height:32px;border:1px solid var(--pink);border-radius:9px;display:grid;place-items:center;color:var(--pink);font-size:17px;box-shadow:0 0 18px #ff4db822}
.brand b {
color:var(--pink)}
.top-right {
display:flex;align-items:center;gap:22px;color:#a6a4b8;font:11px var(--mono);letter-spacing:.12em}
.live-dot {
display:inline-block;width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 9px var(--lime);margin-right:8px}
.main {
display:grid;grid-template-columns:minmax(0,1fr) 292px;gap:22px;padding-top:26px}
.eyebrow {
font:10px var(--mono);letter-spacing:.2em;color:var(--pink);text-transform:uppercase}
.heading-row {
display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:16px}
.heading-row h1 {
font-size:30px;line-height:1;margin:8px 0 0;letter-spacing:-.05em}
.heading-row p {
margin:9px 0 0;color:var(--muted);font-size:13px}
.session-chip {
font:10px var(--mono);color:#aaa9b9;border:1px solid var(--line);border-radius:20px;padding:8px 11px}
.game-shell {
position:relative;background:#0d0e17;border:1px solid #2c2a3a;border-radius:16px;overflow:hidden;box-shadow:0 20px 70px #0007}
.game-top {
height:58px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff12;background:#12121d}
.song-meta {
display:flex;gap:11px;align-items:center;min-width:0}
.cover {
width:36px;height:36px;border-radius:8px;background:linear-gradient(135deg,#fb4fbb,#714aff 55%,#52e3e5);display:grid;place-items:center;font-size:15px;box-shadow:0 0 20px #b34dff33}
.song-title {
font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:240px}
.song-sub {
color:var(--muted);font:9px var(--mono);margin-top:3px}
.game-stats {
display:flex;gap:23px;font:10px var(--mono);align-items:center}
.stat label {
color:var(--muted);display:block;font-size:8px;letter-spacing:.14em;margin-bottom:4px}
.stat strong {
font-size:13px;font-weight:500}
.stat.score strong {
color:var(--cyan)}
.board {
position:relative;height:min(60vh,570px);min-height:390px;overflow:hidden;background:radial-gradient(ellipse at 50% 100%,#3b1a4a33,transparent 50%),linear-gradient(180deg,#10101b 0%,#13121e 100%);touch-action:none}
.board:before {
content:'';position:absolute;inset:0;background-image:linear-gradient(#ffffff08 1px,transparent 1px),linear-gradient(90deg,#ffffff06 1px,transparent 1px);background-size:100% 68px,25% 100%;pointer-events:none}
.board:after {
content:'';position:absolute;left:0;right:0;bottom:67px;height:1px;background:linear-gradient(90deg,transparent,var(--pink),var(--cyan),transparent);box-shadow:0 0 18px #ff4db866;opacity:.7}
.lane-lines {
position:absolute;inset:0;display:grid;grid-template-columns:repeat(4,1fr);pointer-events:none}
.lane-lines span {
border-right:1px solid #ffffff0b}
.lane-lines span:last-child {
border:0}
.note-layer {
position:absolute;inset:0;overflow:hidden}
.tile {
position:absolute;border-radius:8px;border:1px solid #ffffff55;box-shadow:0 0 19px var(--glow);transition:filter .08s;overflow:hidden}
.tile.normal {
height:65px;background:linear-gradient(135deg,var(--tile),color-mix(in srgb,var(--tile),#161421 34%))}
.tile.long {
background:linear-gradient(180deg,color-mix(in srgb,var(--tile),white 8%),color-mix(in srgb,var(--tile),#17131f 44%));border-radius:9px}
.tile.long:after {
content:'';position:absolute;left:50%;top:7px;bottom:7px;width:2px;background:#ffffff8a;box-shadow:0 0 9px white}
.tile.hit {
filter:brightness(2);transform:scale(.97)}
.hitline {
position:absolute;bottom:66px;left:0;right:0;height:4px;background:linear-gradient(90deg,transparent,#ff4db8,#54e8ef,transparent);filter:drop-shadow(0 0 7px #ff4db8);opacity:.85}
.keys {
position:absolute;bottom:0;left:0;right:0;height:62px;display:grid;grid-template-columns:repeat(4,1fr);background:#13131e;border-top:1px solid #ffffff12}
.key {
border:0;border-right:1px solid #ffffff12;background:transparent;color:#aaa9bd;display:flex;align-items:center;justify-content:center;gap:7px;transition:.12s}
.key:last-child {
border:0}
.key kbd {
font:10px var(--mono);border:1px solid #ffffff28;border-radius:4px;padding:4px 6px;color:#77768c}
.key.active,.key:active {
background:#ff4db81d;color:white;box-shadow:inset 0 2px var(--pink)}
.key.active kbd {
border-color:var(--pink);color:var(--pink)}
.overlay {
position:absolute;inset:0;z-index:3;display:grid;place-items:center;background:linear-gradient(#0b0b13a8,#0b0b13b8);text-align:center;backdrop-filter:blur(3px)}
.overlay.hidden {
display:none}
.overlay-box {
padding:24px}
.play-mark {
width:62px;height:62px;border:1px solid #ff4db877;border-radius:50%;display:grid;place-items:center;margin:0 auto 15px;color:var(--pink);font-size:24px;box-shadow:0 0 30px #ff4db822}
.overlay h2 {
font-size:24px;margin:0 0 7px}
.overlay p {
font-size:12px;color:#aaa9bb;margin:0 0 18px}
.primary {
border:0;border-radius:7px;color:#180d19;background:var(--pink);padding:12px 21px;font-weight:700;font-size:11px;letter-spacing:.1em;box-shadow:0 7px 25px #ff4db833;transition:.15s}
.primary:hover {
transform:translateY(-2px);box-shadow:0 10px 28px #ff4db855}
.game-controls {
height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 15px;border-top:1px solid #ffffff0c;background:#11111a}
.progress-wrap {
display:flex;align-items:center;gap:10px;flex:1;max-width:500px}
.time {
font:9px var(--mono);color:#8f8da2;min-width:32px}
.progress {
height:3px;background:#333241;border-radius:4px;flex:1;overflow:hidden}
.progress i {
display:block;width:0;height:100%;background:var(--pink);box-shadow:0 0 9px var(--pink)}
.icon-btn {
width:32px;height:30px;border:0;background:transparent;color:#9290a3;border-radius:6px}
.icon-btn:hover {
color:white;background:#ffffff10}
.side {
display:flex;flex-direction:column;gap:14px}
.card {
background:linear-gradient(145deg,#14141f,#101019);border:1px solid var(--line);border-radius:13px;padding:17px}
.card-head {
display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.card-head h3 {
margin:0;font-size:12px;letter-spacing:.02em}
.tiny {
font:9px var(--mono);color:var(--muted)}
.upload {
width:100%;height:104px;border:1px dashed #4b3b58;border-radius:9px;background:#ff4db808;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;transition:.15s}
.upload:hover {
border-color:var(--pink);background:#ff4db811}
.upload .plus {
font-size:19px;color:var(--pink);line-height:1}
.upload strong {
font-size:11px}
.upload small {
font-size:9px;color:var(--muted)}
.file-note {
font-size:10px;line-height:1.55;color:#77768a;margin:11px 1px 0}
.file-note b {
color:#aaa8bc;font-weight:500}
.track-row {
display:flex;align-items:center;gap:10px;padding:9px;border-radius:8px;background:#ffffff06}
.track-thumb {
width:34px;height:34px;border-radius:7px;background:linear-gradient(140deg,#50d4dc,#9c4eff);display:grid;place-items:center;font-size:13px}
.track-info {
flex:1;min-width:0}
.track-info strong {
display:block;font-size:10px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}
.track-info small {
color:var(--muted);font:9px var(--mono)}
.track-bpm {
font:9px var(--mono);color:var(--cyan)}
.control-row {
display:flex;align-items:center;justify-content:space-between;padding:9px 0;border-bottom:1px solid #ffffff0b}
.control-row:last-child {
border:0;padding-bottom:0}
.control-row label {
font-size:10px;color:#b1afc0}
.value {
font:10px var(--mono);color:var(--cyan)}
.range {
width:100%;accent-color:var(--pink);height:3px;margin:10px 0 0}
.toggle {
appearance:none;width:29px;height:16px;border-radius:12px;background:#353443;position:relative;cursor:pointer;transition:.2s}
.toggle:before {
content:'';position:absolute;width:10px;height:10px;left:3px;top:3px;background:#999;border-radius:50%;transition:.2s}
.toggle:checked {
background:#b33185}
.toggle:checked:before {
transform:translateX(13px);background:white}
.howto {
display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:3px}
.howto span {
text-align:center;border:1px solid #ffffff15;background:#ffffff05;border-radius:5px;padding:6px 0;color:#88869a;font:9px var(--mono)}
.howto span b {
color:#e2dfee;font-weight:400}
.footer {
display:flex;justify-content:space-between;margin-top:16px;color:#68677a;font:9px var(--mono);letter-spacing:.08em}
.toast {
position:fixed;left:50%;bottom:28px;transform:translate(-50%,20px);background:#191824;border:1px solid #ffffff20;border-radius:8px;padding:11px 16px;font-size:11px;opacity:0;pointer-events:none;transition:.2s;z-index:10}
.toast.show {
opacity:1;transform:translate(-50%,0)}
.toast b {
color:var(--pink)}
#fileInput {
display:none}

@media(max-width:900px) {
.app {
padding:0 22px 24px}
.main {
grid-template-columns:minmax(0,1fr) 260px;gap:14px}
.game-stats {
gap:12px}
.board {
height:56vh;min-height:360px}
.heading-row h1 {
font-size:27px}
}

@media(max-width:680px) {
.app {
padding:0 12px 18px}
.topbar {
height:60px}
.brand {
font-size:14px;gap:8px}
.brand-icon {
width:28px;height:28px}
.top-right {
gap:0;font-size:7px}
.top-right span:last-child {
display:none}
.main {
display:flex;flex-direction:column;padding-top:19px;gap:12px}
.heading-row {
margin-bottom:12px}
.heading-row h1 {
font-size:25px}
.heading-row p {
font-size:11px}
.session-chip {
font-size:8px;padding:7px}
.board {
height:55vh;min-height:340px;max-height:490px}
.game-top {
height:52px;padding:0 9px}
.game-stats {
gap:7px}
.stat label {
font-size:6px;letter-spacing:.06em}
.stat strong {
font-size:10px}
.song-title {
max-width:95px;font-size:10px}
.song-sub {
font-size:8px}
.side {
display:grid;grid-template-columns:1fr 1fr}
.side .card:first-child {
grid-column:1/-1}
.side .card {
padding:13px}
.upload {
height:76px}
.file-note {
margin-top:7px;font-size:9px}
.side .card:nth-child(2) {
display:none}
.footer {
font-size:8px}
.game-controls {
padding:0 9px}
.key {
font-size:11px}
.key kbd {
font-size:9px}
.howto span {
font-size:8px}
}

